function renderHome(){const done=state.completed.length;$('#page-home').innerHTML=`<div class="hero-home"><p class="eyebrow">Selamat datang, penjelajah</p><h1>Temukan matematika<br>di balik keindahan motif.</h1><p>Jelajahi batik Sulawesi Selatan, pahami pola dan transformasi, lalu ciptakan motifmu sendiri. Mulai dari hal yang terlihat—lanjutkan dengan rasa ingin tahu.</p><div class="hero-actions"><button class="btn btn-gold" data-page="materi">Mulai Belajar ↗</button><button class="btn btn-ghost" data-page="galeri">Jelajahi Galeri</button></div><div class="hero-stats"><div class="hero-stat"><b>${done}/6</b><span>Bab selesai</span></div><div class="hero-stat"><b>${state.score}</b><span>Poin terkumpul</span></div><div class="hero-stat"><b>${state.works.length}</b><span>Karya tersimpan</span></div></div></div>
<div class="dashboard-grid"><article class="panel progress-panel"><div class="panel-top"><h3>Perjalanan belajarmu</h3><span class="pill">${Math.round(done/6*100)}% selesai</span></div><p class="muted">Selesaikan bab secara bertahap. Progres tersimpan otomatis di perangkat ini.</p><div class="progress-track"><div class="progress-fill" style="width:${done/6*100}%"></div></div><div class="progress-caption"><span>${done} dari 6 bab</span><span>${6-done} bab tersisa</span></div><div class="inline-actions"><button class="btn btn-small" data-page="materi">Lanjutkan belajar</button><button class="btn btn-small btn-ghost" data-page="progres">Lihat pencapaian</button></div></article>
<article class="panel daily-panel"><div class="panel-top"><h3>✨ Tantangan hari ini</h3><span class="pill">1 menit</span></div><div class="daily-question">${state.dailyDone?'Tantangan hari ini sudah selesai. Siap mencoba aktivitas lain?':'Jika delapan motif tersusun merata mengelilingi pusat, berapa sudut antar motif?'}</div><button class="btn btn-small ${state.dailyDone?'btn-ghost':''}" id="dailyBtn">${state.dailyDone?'Lihat kuis lainnya':'Jawab tantangan'}</button></article></div>
<div class="section-head"><div><h2>Pilih perjalananmu</h2><p>Lima cara belajar, satu semesta pengetahuan.</p></div></div><div class="dashboard-grid">
${[['📖','Ruang Belajar','Enam bab, ringkasan, contoh, dan praktik.','materi'],['🧵','Galeri Motif','Lihat motif, cerita budaya, dan peluang geometri.','galeri'],['🎨','Studio Kreasi','Putar, cerminkan, dan rancang pola sendiri.','studio'],['🎮','Dunia Tantangan','Kuis, pasangkan makna, dan uji transformasi.','games'],['🏆','Perjalanan Saya','Pantau progres, skor, karya, dan lencana.','progres']].map(x=>`<button class="feature-card" data-page="${x[3]}"><span class="arrow">↗</span><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></button>`).join('')}</div>
<div class="section-head"><div><h2>Peta perjalanan</h2><p>Buka satu gerbang, lalu lanjutkan ke penemuan berikutnya.</p></div></div><div class="journey-grid">${chapters.map((c,i)=>`<button class="journey-step" data-chapter="${i}"><span class="step-icon">${state.completed.includes(i)?'✓':['🌱','🧵','🔷','☼','⌘','✦'][i]}</span><b>Gerbang ${i+1}</b><small>${state.completed.includes(i)?'Selesai':safe(c.title.split(':')[0])}</small></button>`).join('')}</div>
<div class="detail-article" style="margin-top:24px"><p class="eyebrow">Catatan perjalanan</p><h2>“${'Setiap pola adalah bahasa, setiap garis adalah doa, setiap motif adalah cerminan keseimbangan semesta.'}”</h2><p>Mulai dari motif kecil, amati dengan teliti, cari sumber yang dapat dipercaya, dan biarkan pertanyaan membawamu pada makna yang lebih besar.</p></div>`;
$('#dailyBtn').onclick=()=>{if(state.dailyDone){go('games');startQuiz();return}openModal(`<p class="eyebrow">Tantangan hari ini</p><h2>Delapan motif mengelilingi pusat</h2><p>Jika delapan posisi tersebar merata pada satu putaran, berapa sudut antarposisi?</p><div class="inline-actions"><button class="btn" data-daily-answer="30">30°</button><button class="btn" data-daily-answer="45">45°</button><button class="btn" data-daily-answer="90">90°</button></div><div id="dailyFeedback"></div>`);$$('[data-daily-answer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.dailyAnswer==='45';$('#dailyFeedback').innerHTML=`<div class="quiz-feedback">${ok?'Tepat!':'Belum tepat.'} Satu putaran adalah 360°, sehingga 360° ÷ 8 = 45°.</div><button class="btn btn-small" id="dailyDoneBtn">Selesai</button>`;if(ok&&!state.dailyDone){state.score+=10;state.dailyDone=true;save()}$('#dailyDoneBtn').onclick=()=>{closeModal();renderHome();toast(ok?'Tantangan selesai · +10 poin':'Tetap semangat, coba lagi di kuis!')};});};}
function renderChapters(){const p=$('#page-materi');p.innerHTML=`<p class="eyebrow">Ruang belajar</p><h1 class="page-title">Belajar selapis demi selapis.</h1><p class="lead">Enam bab dari buku Anyaman Semesta. Mulai dari pengamatan, pahami konsep, lalu lakukan praktik sederhana. Setiap bab memiliki ringkasan, penjelasan, aktivitas, dan refleksi.</p><div class="chapter-grid">${chapters.map((c,i)=>`<article class="chapter-card"><div class="chapter-top"><span class="pill">${c.part}</span><span class="chapter-number">0${i+1}</span></div><h3>${c.title}</h3><p>${c.summary}</p><div class="chapter-footer"><span class="muted" style="font-size:.78rem">${state.completed.includes(i)?'✓ Sudah selesai':'± 5–8 menit'}</span><button class="btn btn-small" data-open-chapter="${i}">${state.completed.includes(i)?'Baca ulang':'Mulai bab'} ↗</button></div></article>`).join('')}</div><div id="chapterDetail"></div>`;$$('[data-open-chapter]').forEach(b=>b.onclick=()=>showChapter(+b.dataset.openChapter));}
function showChapter(i){const c=chapters[i];const detail=$('#chapterDetail');detail.innerHTML=`<article class="detail-article" id="activeChapter"><p class="eyebrow">${c.part} · Bab ${i+1}</p><h2>${c.title}</h2><p class="lead">${c.summary}</p>${c.sections.map(([h,t])=>`<h3>${h}</h3><p>${t}</p>`).join('')}<div class="callout"><b>🧪 Coba sendiri</b><br>${c.practice}</div><h3>Inti yang perlu diingat</h3><p>${c.takeaway}</p>${c.resources?.length?`<h3>🔎 Rujukan dan penelusuran lanjutan</h3><ul class="chapter-resources">${c.resources.map(([label,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${safe(label)} ↗</a></li>`).join('')}</ul>`:''}<div class="inline-actions"><button class="btn" id="completeChapter">${state.completed.includes(i)?'Bab sudah ditandai selesai':'Tandai bab selesai ✓'}</button>${c.link?`<a class="btn btn-ghost" href="${c.link}" target="_blank" rel="noopener">Buka GeoGebra ↗</a>`:''}<button class="btn btn-ghost" id="backChapters">Kembali ke daftar</button></div></article>`;$('#completeChapter').onclick=()=>{if(!state.completed.includes(i)){state.completed.push(i);state.score+=20;save();awardBadges();toast('Bab selesai · +20 poin')}renderChapters();renderHome();renderProgress();showChapter(i);};$('#backChapters').onclick=()=>detail.innerHTML='';detail.scrollIntoView({behavior:'smooth',block:'start'});}
function renderGallery(){const p=$('#page-galeri');p.innerHTML=`<p class="eyebrow">Galeri budaya</p><h1 class="page-title">Setiap motif punya cerita.</h1><p class="lead">Galeri memuat katalog lintas wilayah dengan prioritas Sulawesi, termasuk 142 kartu penelusuran. Galeri mencoba memuat foto rujukan yang judulnya memiliki kecocokan kuat dengan nama motif. Hasil daring tetap perlu diverifikasi pada halaman sumber; foto yang tidak cocok tidak dipaksakan tampil. Pilih <b>Studio</b> pada kartu mana pun untuk mengolah foto yang tersedia.</p><div class="gallery-tools"><input id="gallerySearch" class="field" placeholder="Cari motif, bentuk, atau wilayah…" aria-label="Cari galeri"><select id="galleryFilter" class="field"><option value="all">Semua kategori</option><option>Motif Sulawesi</option><option>Motif Nusantara</option><option>Budaya lokal</option><option>Aksara & identitas</option><option>Sastra & cerita</option><option>Arsitektur & ornamen</option><option>Motif kerbau</option><option>Anyaman & pola</option><option>Pola garis</option><option>Inspirasi desain</option></select></div><div class="gallery-grid" id="galleryGrid">${motifs.map((m,i)=>motifCard(m,i)).join('')}</div><div class="source-note"><b>Tentang foto dan sumber:</b> Foto rujukan dicari di Wikimedia Commons dengan pencocokan nama yang ketat. Pencocokan judul bukan bukti autentikasi budaya, jadi periksa halaman sumber, asal, dan lisensi sebelum mengutip atau menerbitkan. Jika foto tidak ditemukan atau gagal dimuat, ilustrasi pola lokal tetap tampil sebagai cadangan, dengan tautan pencarian foto asli berdasarkan nama motif.</div><div class="inline-actions"><a class="btn btn-ghost" href="https://commons.wikimedia.org/wiki/Special:MediaSearch?type=image&search=batik+Indonesia" target="_blank" rel="noopener">Cari foto batik Nusantara ↗</a><a class="btn btn-ghost" href="https://www.iwarebatik.org/south-sulawesi/?lang=id" target="_blank" rel="noopener">Jelajahi sumber iWareBatik ↗</a><a class="btn btn-ghost" href="https://ich.unesco.org/en/RL/batik-00170" target="_blank" rel="noopener">Batik Indonesia · UNESCO ↗</a></div>`;
$('#gallerySearch').oninput=filterGallery;$('#galleryFilter').onchange=filterGallery;$$('[data-motif]').forEach(b=>b.onclick=()=>openMotif(+b.dataset.motif));
$$('[data-motif-img]').forEach(img=>img.onerror=()=>{img.onerror=null;const fallback=img.dataset.fallback;if(fallback&&img.src!==new URL(fallback,location.href).href){img.src=fallback;return;}const badge=img.closest('.motif-image')?.querySelector('.motif-badge');if(badge)badge.textContent='Ilustrasi cadangan';});
// Muat foto asli dari Wikimedia Commons saat kartu mendekati layar. Tidak ada SVG/sketsa sebagai pengganti foto.
// Muat foto untuk SELURUH katalog, bukan hanya kartu yang kebetulan terlihat. Antrean membatasi permintaan agar Commons tidak dibanjiri sekaligus.
const galleryPhotoQueue=$$('[data-card-motif]').map(card=>+card.dataset.cardMotif);let galleryPhotoQueueRunning=0;const runGalleryPhotoQueue=()=>{while(galleryPhotoQueueRunning<3&&galleryPhotoQueue.length){const i=galleryPhotoQueue.shift();galleryPhotoQueueRunning++;loadAuthenticPhoto(i).catch(()=>{}).finally(()=>{galleryPhotoQueueRunning--;runGalleryPhotoQueue()})}};runGalleryPhotoQueue();
}

function googleImagesUrl(m){return 'https://www.google.com/search?tbm=isch&q='+encodeURIComponent((m?.name||'motif batik')+' batik Indonesia '+(m?.region||''));}
function motifCard(m,i){const fallback=`assets/gallery/pola-${String(i+1).padStart(3,'0')}.svg`;return `<article class="motif-card" data-card-motif="${i}" tabindex="0" role="button" aria-label="Baca tentang ${safe(m.name)}"><div class="motif-image"><img loading="lazy" data-motif-img="${i}" src="${fallback}" data-fallback="${fallback}" alt="Ilustrasi pola pendamping untuk ${safe(m.name)}"><span class="motif-badge" data-motif-badge="${i}">Ilustrasi motif · mencari foto</span></div><div class="motif-card-body"><h3>${safe(m.name)}</h3><p>${safe(m.description.slice(0,130))}${m.description.length>130?'…':''}</p><div class="inline-actions"><a href="${m.source}" target="_blank" rel="noopener" onclick="event.stopPropagation()">Sumber & cerita ↗</a><a href="${googleImagesUrl(m)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">Cari di Google Images ↗</a><button type="button" class="btn btn-small" data-studio-motif="${i}" onclick="event.stopPropagation()">🎨 Studio</button></div><small class="photo-credit" data-photo-credit="${i}">Ilustrasi lokal ditampilkan sebagai cadangan sambil mencari foto dari web.</small></div></article>`}
const usedAuthenticPhotoPages=new Set();
async function loadAuthenticPhoto(i){
 const m=motifs[i];if(!m||m.photoUrl||m.photoChecked)return;m.photoChecked=true;
 const img=$(`[data-motif-img="${i}"]`),badge=$(`[data-motif-badge="${i}"]`),credit=$(`[data-photo-credit="${i}"]`);if(!img)return;
 const clean=s=>String(s||'').replace(/<[^>]*>/g,'').replace(/&quot;/g,'"').replace(/&#039;/g,"'");
 const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
 const tokens=norm(m.name).split(/\s+/).filter(w=>w.length>2&&!['motif','batik','inspirasi','warna','dan','geometri'].includes(w));
 const queries=[`"${m.name}"`,`${m.name} batik`,`${m.name} motif Indonesia`];
 const search=async q=>{const u=`https://commons.wikimedia.org/w/api.php?action=query&list=search&srnamespace=6&srsearch=${encodeURIComponent(q)}&srlimit=20&format=json&origin=*`;const r=await fetch(u);if(!r.ok)throw Error('Commons HTTP '+r.status);const d=await r.json();return d.query?.search||[]};
 try{let candidate=null;for(const q of queries){let results=[];try{results=await search(q)}catch(e){continue}const ranked=results.filter(x=>!/(logo|map|diagram|icon|flag|coat of arms|svg|poster|book cover)/i.test(x.title)).map(x=>{const t=norm(x.title.replace(/^File:/,'')),matched=tokens.filter(w=>t.includes(w));return {...x,score:matched.length,exact:matched.length===tokens.length,textile:/batik|textile|kain|cloth|fabric|motif|pattern/i.test(x.title)}}).filter(x=>x.score>=Math.max(1,Math.ceil(tokens.length*.75))&&x.textile).sort((a,b)=>Number(b.exact)-Number(a.exact)||b.score-a.score);candidate=ranked.find(x=>!usedAuthenticPhotoPages.has(x.pageid));if(candidate)break}
 if(!candidate)throw Error('Tidak ada hasil yang cukup cocok dengan nama motif');const r=await fetch(`https://commons.wikimedia.org/w/api.php?action=query&pageids=${candidate.pageid}&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=900&format=json&origin=*`);if(!r.ok)throw Error('Metadata gagal');const d=await r.json(),info=d.query?.pages?.[candidate.pageid]?.imageinfo?.[0],photo=info?.thumburl||info?.url;if(!photo||usedAuthenticPhotoPages.has(candidate.pageid))throw Error('Foto tidak tersedia atau sudah dipakai');usedAuthenticPhotoPages.add(candidate.pageid);m.photoUrl=photo;m.photoPage='https://commons.wikimedia.org/wiki/'+encodeURIComponent(candidate.title.replaceAll(' ','_'));m.photoTitle=candidate.title.replace(/^File:/,'');m.photoLicense=clean(info.extmetadata?.LicenseShortName?.value)||'Periksa lisensi di halaman sumber';m.photoAuthor=clean(info.extmetadata?.Artist?.value||'');img.onload=()=>img.closest('.motif-image')?.classList.remove('photo-loading','photo-unavailable');img.onerror=()=>{img.onerror=null;img.src=img.dataset.fallback||`assets/gallery/pola-${String(i+1).padStart(3,'0')}.svg`;img.closest('.motif-image')?.classList.remove('photo-loading','photo-unavailable');if(badge)badge.textContent='Ilustrasi cadangan · foto gagal dimuat'};img.src=photo;img.alt=`Foto rujukan ${m.photoTitle}; cocokkan dengan nama motif ${m.name} melalui halaman sumber`;if(badge)badge.textContent='Foto rujukan ditemukan · verifikasi sumber';if(credit)credit.innerHTML=`Foto: <a href="${m.photoPage}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${safe(m.photoTitle)}</a> · ${safe(m.photoLicense)}${m.photoAuthor?' · '+safe(m.photoAuthor):''}`;const modal=$(`[data-modal-photo="${i}"]`);if(modal)modal.src=photo;
 }catch(e){if(badge)badge.textContent='Foto belum dimuat';if(credit)credit.innerHTML='Foto belum berhasil dimuat otomatis. <a href="'+googleImagesUrl(m)+'" target="_blank" rel="noopener" onclick="event.stopPropagation()">Cari foto motif ini di Google Images ↗</a>';img.closest('.motif-image')?.classList.remove('photo-loading','photo-unavailable');m.photoChecked=false}
}
function filterGallery(){const q=$('#gallerySearch').value.toLowerCase(),f=$('#galleryFilter').value;$$('[data-card-motif]').forEach(card=>{const m=motifs[+card.dataset.cardMotif];card.style.display=(m.name+' '+m.region+' '+m.description+' '+m.math).toLowerCase().includes(q)&&(f==='all'||m.category===f)?'':'none'});}
function openMotif(i){const m=motifs[i];if(!m.photoUrl)loadAuthenticPhoto(i);openModal(`<p class="eyebrow">${safe(m.region)} · ${safe(m.category)}</p><h2 class="subheading">${safe(m.name)}</h2><div class="motif-modal-photo-wrap"><img class="motif-modal-image" data-modal-photo="${i}" src="${m.photoUrl||''}" alt="Foto asli ${safe(m.name)}" onerror="this.removeAttribute('src')"><p class="muted" data-modal-photo-status="${i}">${m.photoUrl?'Foto rujukan web. Periksa kecocokan motif dan lisensinya pada sumber.':'Foto asli sedang dicari. Jika tidak ditemukan, gunakan tautan pencarian foto di bawah.'}</p></div><h3>🌿 Cerita budaya</h3><p>${safe(m.description)}</p><h3>🔷 Lihat dengan mata matematis</h3><p>${safe(m.math)}</p><div class="callout"><b>Coba jawab:</b><br>${safe(m.question)}<details style="margin-top:12px"><summary style="cursor:pointer;font-weight:700">Lihat pembahasan</summary><p>${safe(m.answer)}</p></details></div><div class="inline-actions"><a class="btn" href="${m.photoPage||`https://www.google.com/search?tbm=isch&q=${encodeURIComponent(m.name+' batik Indonesia '+m.region)}`}" target="_blank" rel="noopener">Buka foto/sumber ↗</a><button class="btn btn-ghost" data-open-studio="${i}" data-close-modal>🎨 Edit pola di Studio</button></div>`);$$('[data-open-studio]',$('#modalBody')).forEach(b=>b.onclick=()=>{studioMotifIndex=+b.dataset.openStudio;studioPhoto=motifs[studioMotifIndex].photoUrl||null;closeModal();go('studio')});}
let rotation=45,scale=1,mirror=true,translate=20,selectedColor=0,studioMotifIndex=null,studioPhoto=null,studioShape='flower',studioBackground='#f8edda',studioDensity=8;const palette=['#8e3025','#d7a548','#354d37','#241b19','#f4dfb5'];
function renderStudio(){const p=$('#page-studio');p.innerHTML=`<p class="eyebrow">Studio kreasi</p><h1 class="page-title">Satu coretan, banyak kemungkinan.</h1><p class="lead">Buat pola sendiri atau mulai dari foto motif pilihanmu. Atur bentuk dasar, jumlah pengulangan, rotasi, cermin, jarak, warna, dan latar. Jika foto asli tersedia, gunakan sebagai inspirasi; kamu juga dapat merancang pola geometris orisinal.</p><div id="studioMotifInfo" class="callout">${studioMotifIndex!==null?`Motif terpilih: ${safe(motifs[studioMotifIndex]?.name||'Motif')}`:'Pilih tombol Studio pada kartu galeri untuk mulai mengedit motif tertentu.'}</div><div class="studio-layout"><div class="studio-canvas-wrap"><canvas id="motifCanvas" width="700" height="700" aria-label="Kanvas motif interaktif"></canvas><div class="inline-actions"><button class="btn btn-small" id="savePng">Simpan sebagai PNG ↓</button><button class="btn btn-small btn-ghost" id="resetStudio">Atur ulang</button></div></div><div class="panel studio-controls"><h3 class="subheading">Atur pola</h3><div class="control-row"><label for="shapeSelect">Bentuk dasar</label><select class="field" id="shapeSelect"><option value="flower">Bunga / roset</option><option value="diamond">Belah ketupat</option><option value="wave">Gelombang</option><option value="star">Bintang</option><option value="circle">Lingkaran</option><option value="photo">Foto motif terpilih</option></select></div><div class="control-row"><label for="densityRange">Jumlah pengulangan <span id="densityVal">8</span></label><input id="densityRange" type="range" min=1 max=24 step=1 value=8></div><div class="control-row"><label for="backgroundSelect">Latar kanvas</label><select class="field" id="backgroundSelect"><option value="#f8edda">Krem kain</option><option value="#ffffff">Putih</option><option value="#17324a">Biru laut</option><option value="#263b2b">Hijau tua</option><option value="#211a18">Cokelat gelap</option></select></div><div class="control-row"><label for="rotRange">Rotasi <span id="rotVal">45°</span></label><input id="rotRange" type="range" min="0" max="360" step="15" value="45"></div><div class="control-row"><label for="scaleRange">Skala <span id="scaleVal">1.0×</span></label><input id="scaleRange" type="range" min="0.5" max="1.5" step="0.1" value="1"></div><div class="control-row"><label for="transRange">Pergeseran pola <span id="transVal">20</span></label><input id="transRange" type="range" min="0" max="100" step="5" value="20"></div><div class="control-row"><label>Pencerminan</label><button id="mirrorBtn" class="btn btn-small">Cermin: aktif ✓</button></div><div class="control-row"><label>Palet warna</label><div class="color-row">${palette.map((c,i)=>`<button class="color-swatch ${i===0?'selected':''}" style="background:${c}" data-color="${i}" aria-label="Pilih warna ${i+1}"></button>`).join('')}</div></div><div class="control-row"><label>Keseimbangan visual</label><div class="mizan-meter"><span id="mizanFill"></span></div><small id="mizanText" class="muted">Pola tersusun dari pusat dan diulang secara teratur.</small></div><div class="source-note">Tips: coba 45°, 90°, dan 180°. Untuk menguji pengubinan, gunakan Dunia Tantangan. Simetri matematis tidak otomatis membuktikan makna spiritual tertentu.</div></div></div><div class="detail-article"><h2>🔬 Apa yang sedang berubah?</h2><p id="studioExplain">Rotasi memutar pola di sekitar pusat. Coba ubah slider dan amati bagian yang tetap.</p></div>`;
['rotRange','scaleRange','transRange','densityRange'].forEach(id=>$('#'+id).oninput=()=>{rotation=+$('#rotRange').value;scale=+$('#scaleRange').value;translate=+$('#transRange').value;studioDensity=+$('#densityRange').value;$('#rotVal').textContent=rotation+'°';$('#scaleVal').textContent=scale.toFixed(1)+'×';$('#transVal').textContent=translate;$('#densityVal').textContent=studioDensity;drawPattern();});$('#shapeSelect').onchange=()=>{studioShape=$('#shapeSelect').value;drawPattern()};$('#backgroundSelect').onchange=()=>{studioBackground=$('#backgroundSelect').value;drawPattern()};$('#mirrorBtn').onclick=()=>{mirror=!mirror;$('#mirrorBtn').textContent='Cermin: '+(mirror?'aktif ✓':'nonaktif');drawPattern()};$$('[data-color]').forEach(b=>b.onclick=()=>{selectedColor=+b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('selected',x===b));drawPattern()});$('#resetStudio').onclick=()=>{rotation=45;scale=1;translate=20;mirror=true;selectedColor=0;studioShape='flower';studioBackground='#f8edda';studioDensity=8;$('#shapeSelect').value='flower';$('#backgroundSelect').value='#f8edda';$('#densityRange').value=8;$('#densityVal').textContent='8';$('#rotRange').value=45;$('#scaleRange').value=1;$('#transRange').value=20;$('#rotVal').textContent='45°';$('#scaleVal').textContent='1.0×';$('#transVal').textContent='20';$('#mirrorBtn').textContent='Cermin: aktif ✓';$$('[data-color]').forEach((x,i)=>x.classList.toggle('selected',i===0));drawPattern()};$('#savePng').onclick=()=>{try{const a=document.createElement('a');a.download='karya-anyaman-semesta.png';a.href=$('#motifCanvas').toDataURL('image/png');a.click();const motif=studioMotifIndex!==null?motifs[studioMotifIndex]:null;state.works.push({name:motif?`Karya ${motif.name}`:'Karya '+(state.works.length+1),date:new Date().toLocaleDateString('id-ID'),rotation,scale,mirror,color:palette[selectedColor]});state.score+=5;save();awardBadges();renderProgress();toast('Karya disimpan sebagai PNG · +5 poin')}catch(err){toast('Foto sumber membatasi ekspor. Coba gunakan sketsa lokal atau periksa koneksi sumber.')}};drawPattern();}
function drawStudioShape(ctx,shape,color){ctx.strokeStyle=color;ctx.fillStyle=color+'26';ctx.lineWidth=4;ctx.beginPath();if(shape==='circle'){ctx.arc(55,0,28,0,Math.PI*2)}else if(shape==='wave'){ctx.moveTo(0,0);ctx.quadraticCurveTo(28,-55,56,0);ctx.quadraticCurveTo(84,55,112,0)}else if(shape==='star'){for(let j=0;j<10;j++){const r=j%2?19:42,a=-Math.PI/2+j*Math.PI/5,x=55+Math.cos(a)*r,y=Math.sin(a)*r;j?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath()}else if(shape==='diamond'){ctx.moveTo(55,-48);ctx.lineTo(105,0);ctx.lineTo(55,48);ctx.lineTo(5,0);ctx.closePath()}else{ctx.moveTo(55,-45);ctx.bezierCurveTo(5,-65,0,-5,55,45);ctx.bezierCurveTo(110,-5,105,-65,55,-45);ctx.closePath();ctx.moveTo(55,-25);ctx.lineTo(55,25)}ctx.fill();ctx.stroke();}
function drawPattern(){const canvas=$('#motifCanvas');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,cx=w/2,cy=h/2;ctx.clearRect(0,0,w,h);ctx.fillStyle=studioBackground;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#d8c4a2';ctx.lineWidth=1;for(let x=35;x<w;x+=35){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=35;y<h;y+=35){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#b9975c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(cx,cy,210,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d6a84c';ctx.beginPath();ctx.arc(cx,cy,9,0,Math.PI*2);ctx.fill();const n=studioDensity||8;const ang=2*Math.PI/n;const motif=studioMotifIndex!==null?motifs[studioMotifIndex]:null;let source=(studioShape==='photo'?(studioPhoto||(motif?.photoUrl||null)):null);let photoImg=null;if(source){photoImg=new Image();photoImg.crossOrigin='anonymous';photoImg.src=source;if(!photoImg.complete||!photoImg.naturalWidth){photoImg=null;const pending=new Image();pending.crossOrigin='anonymous';pending.onload=()=>{if($('#motifCanvas'))drawPattern()};pending.src=source;}}
for(let i=0;i<n;i++){ctx.save();ctx.translate(cx,cy);ctx.rotate(i*ang);ctx.scale(scale,scale);const shift=translate*(mirror?0.55:1);ctx.translate(shift,0);if(photoImg){const max=155,ratio=Math.min(max/photoImg.naturalWidth,max/photoImg.naturalHeight),iw=photoImg.naturalWidth*ratio,ih=photoImg.naturalHeight*ratio;ctx.save();ctx.translate(-iw/2,-ih/2);ctx.drawImage(photoImg,0,0,iw,ih);ctx.globalCompositeOperation='source-atop';ctx.globalAlpha=.22;ctx.fillStyle=palette[selectedColor];ctx.fillRect(0,0,iw,ih);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.restore();}else{ctx.strokeStyle=palette[selectedColor];ctx.fillStyle=palette[selectedColor]+'26';ctx.lineWidth=4;drawStudioShape(ctx,studioShape,palette[selectedColor]);}if(mirror){ctx.save();ctx.scale(-1,1);if(photoImg){const max=155,ratio=Math.min(max/photoImg.naturalWidth,max/photoImg.naturalHeight),iw=photoImg.naturalWidth*ratio,ih=photoImg.naturalHeight*ratio;ctx.drawImage(photoImg,-iw/2,-ih/2,iw,ih);ctx.globalCompositeOperation='source-atop';ctx.globalAlpha=.22;ctx.fillStyle=palette[selectedColor];ctx.fillRect(-iw/2,-ih/2,iw,ih);ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over'}else{drawStudioShape(ctx,studioShape,palette[selectedColor])}ctx.restore()}ctx.restore()}
$('#studioExplain').textContent=`${motif?'Motif terpilih: '+motif.name+'. ':''}Pola memakai ${n} posisi berulang dengan sudut antarposisi kira-kira ${(360/n).toFixed(0)}°. Skala ${scale.toFixed(1)}×, pencerminan ${mirror?'aktif':'nonaktif'}, pergeseran ${translate}. ${photoImg?'Foto motif dipakai sebagai unit visual yang dapat diputar, dicerminkan, digeser, dan diskalakan.':'Pola geometris orisinal digunakan; ubah bentuk, jumlah pengulangan, warna, dan latar.'}`;$('#mizanFill').style.width=(mirror?100:Math.max(40,100-translate*.45))+'%';$('#mizanText').textContent=mirror?'Unit pola dicerminkan; periksa hasil visualnya.':'Pola tidak dicerminkan; keseimbangan visual perlu diamati.';}
let quizIndex=0,quizCorrect=0,quizLocked=false;
function renderGames(){const p=$('#page-games');p.innerHTML=`<p class="eyebrow">Dunia tantangan</p><h1 class="page-title">Belajar sambil mencoba.</h1><p class="lead">Pilih permainan. Setiap jawaban disertai pembahasan agar kamu memahami alasan di balik hasilnya.</p><div class="games-grid"><article class="game-card"><span class="game-emoji">🧠</span><h3>Kuis Penjelajah</h3><p>12 pertanyaan tentang pola, transformasi, budaya, dan GeoGebra. Dapatkan poin dan lihat penjelasan.</p><button class="btn" id="startQuiz">Mulai kuis ↗</button></article><article class="game-card"><span class="game-emoji">🃏</span><h3>Pasangkan Motif & Makna</h3><p>Cocokkan istilah dengan keterangan yang tepat. Ingat, makna budaya harus tetap mengikuti sumber.</p><button class="btn" id="startMatch">Mulai mencocokkan ↗</button></article><article class="game-card"><span class="game-emoji">🔄</span><h3>Tebak Transformasi</h3><p>Pelajari situasi, lalu tentukan apakah perubahan merupakan refleksi, rotasi, translasi, atau dilatasi.</p><button class="btn" id="startTransform">Tebak sekarang ↗</button></article><article class="game-card"><span class="game-emoji">⬡</span><h3>Gim Pengubinan</h3><p>Hitung sudut dalam dan cari berapa bentuk yang pas mengelilingi satu titik tanpa celah.</p><button class="btn" id="startTiling">Uji pengubinan ↗</button></article><article class="game-card"><span class="game-emoji">⌘</span><h3>Susun Langkah GeoGebra</h3><p>Atur langkah rekonstruksi pola agar menjadi urutan kerja yang logis.</p><button class="btn" id="startOrder">Susun langkah ↗</button></article></div><div id="gameArea"></div>`;$('#startQuiz').onclick=startQuiz;$('#startMatch').onclick=startMatch;$('#startTransform').onclick=startTransform;$('#startTiling').onclick=startTiling;$('#startOrder').onclick=startOrder;}
function startQuiz(){quizIndex=0;quizCorrect=0;quizLocked=false;renderQuizQuestion();}
function renderQuizQuestion(){const area=$('#gameArea');if(!area)return;if(quizIndex>=quiz.length){state.score+=quizCorrect*5;state.best=Math.max(state.best,quizCorrect);save();awardBadges();renderHome();renderProgress();area.innerHTML=`<article class="detail-article"><p class="eyebrow">Kuis selesai</p><h2>Hebat, penjelajah!</h2><p>Kamu menjawab benar ${quizCorrect} dari ${quiz.length} soal.</p><div class="hero-stats"><div class="hero-stat"><b>${quizCorrect}/${quiz.length}</b><span>Jawaban benar</span></div><div class="hero-stat"><b>+${quizCorrect*5}</b><span>Poin</span></div></div><div class="inline-actions"><button class="btn" id="retryQuiz">Coba lagi</button><button class="btn btn-ghost" data-page="materi">Pelajari materi</button></div></article>`;$('#retryQuiz').onclick=startQuiz;area.scrollIntoView({behavior:'smooth'});return}const q=quiz[quizIndex];quizLocked=false;area.innerHTML=`<article class="detail-article"><div class="quiz-meta"><span>Kuis Penjelajah</span><span>Soal ${quizIndex+1} dari ${quiz.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${quizIndex/quiz.length*100}%"></div></div><h2>${safe(q.q)}</h2><div id="quizOptions">${q.o.map((o,i)=>`<button class="quiz-option" data-answer="${i}">${String.fromCharCode(65+i)}. ${safe(o)}</button>`).join('')}</div><div id="quizFeedback"></div></article>`;$$('[data-answer]',area).forEach(b=>b.onclick=()=>{if(quizLocked)return;quizLocked=true;const correct=+b.dataset.answer===q.a;if(correct)quizCorrect++;$$('[data-answer]',area).forEach(x=>{x.disabled=true;if(+x.dataset.answer===q.a)x.classList.add('correct')});if(!correct)b.classList.add('wrong');$('#quizFeedback').innerHTML=`<div class="quiz-feedback"><b>${correct?'Benar!':'Belum tepat.'}</b> ${safe(q.e)}<div class="inline-actions"><button class="btn btn-small" id="nextQuestion">${quizIndex===quiz.length-1?'Lihat hasil':'Soal berikutnya'} →</button></div></div>`;$('#nextQuestion').onclick=()=>{quizIndex++;renderQuizQuestion()}});area.scrollIntoView({behavior:'smooth',block:'start'});}
function startMatch(){const pairs=[['Pa’tedong','Kepala kerbau; simbol kemuliaan dalam sumber iWareBatik'],['Lontara','Aksara tradisional Bugis-Makassar'],['Translasi','Pergeseran dengan vektor yang sama'],['Rotasi','Perputaran terhadap pusat'],['Mizan','Keseimbangan dan keadilan'],['Tessellation','Menutup bidang tanpa celah dan tumpang tindih']];let cards=pairs.flatMap((p,i)=>[{id:i,side:0,text:p[0]},{id:i,side:1,text:p[1]}]).sort(()=>Math.random()-.5),chosen=[],matched=new Set();$('#gameArea').innerHTML=`<article class="detail-article"><p class="eyebrow">Pasangkan</p><h2>Temukan pasangan yang tepat</h2><p class="muted">Pilih satu kartu istilah, lalu pilih kartu keterangan yang cocok.</p><div class="match-grid" id="matchGrid">${cards.map((c,i)=>`<button class="match-card" data-match="${i}">❔<br><small>Buka kartu</small></button>`).join('')}</div><p id="matchStatus" class="muted">Pasangan ditemukan: 0/${pairs.length}</p></article>`;$$('[data-match]').forEach(b=>b.onclick=()=>{const i=+b.dataset.match;if(matched.has(i)||chosen.some(x=>x.i===i))return;b.innerHTML=safe(cards[i].text);chosen.push({i,c:cards[i]});if(chosen.length===2){const [a,z]=chosen;if(a.c.id===z.c.id&&a.c.side!==z.c.side){matched.add(a.i);matched.add(z.i);$$('[data-match]').forEach(x=>{if(matched.has(+x.dataset.match))x.classList.add('matched')});$('#matchStatus').textContent=`Pasangan ditemukan: ${matched.size/2}/${pairs.length}`;if(matched.size===cards.length){state.score+=30;save();awardBadges();$('#matchStatus').textContent='Selesai! +30 poin. Kamu berhasil menemukan semua pasangan.';renderHome();renderProgress()}}else{setTimeout(()=>{[a,z].forEach(x=>{if(!matched.has(x.i))$(`[data-match="${x.i}"]`).innerHTML='❔<br><small>Buka kartu</small>'})},800)}chosen=[]}});}
function startTransform(){const tasks=[{before:'Segitiga dipindahkan 4 satuan ke kanan, tidak diputar.',opts:['Refleksi','Rotasi','Translasi','Dilatasi'],a:2,why:'Semua titik berpindah dengan vektor yang sama: translasi.'},{before:'Bangun diputar 90° mengelilingi titik O.',opts:['Refleksi','Rotasi','Translasi','Dilatasi'],a:1,why:'Perubahan mengelilingi titik pusat dengan sudut tertentu adalah rotasi.'},{before:'Bentuk dicerminkan terhadap garis vertikal.',opts:['Refleksi','Rotasi','Translasi','Dilatasi'],a:0,why:'Refleksi membentuk bayangan pada sisi lain sumbu dengan jarak yang sama.'},{before:'Semua panjang menjadi 2 kali semula dari pusat tertentu.',opts:['Refleksi','Rotasi','Translasi','Dilatasi'],a:3,why:'Perubahan ukuran dengan faktor skala adalah dilatasi.'}];let idx=0,correct=0;function show(){const t=tasks[idx];$('#gameArea').innerHTML=`<article class="detail-article"><p class="eyebrow">Tebak transformasi · ${idx+1}/${tasks.length}</p><h2>${t.before}</h2><div class="shape-playground"><div class="shape-box"><small>Sebelum</small><svg viewBox="0 0 120 100"><polygon points="25,75 50,25 75,75" fill="#d7a548" stroke="#7d2b20" stroke-width="3"/></svg></div><div class="shape-box"><small>Sesudah (ilustrasi)</small><svg viewBox="0 0 120 100"><polygon points="48,75 73,25 98,75" fill="#d7a548" stroke="#7d2b20" stroke-width="3"/><path d="M12 50H36" stroke="#7d2b20" stroke-width="3" stroke-linecap="round"/><path d="M28 42L36 50L28 58" fill="none" stroke="#7d2b20" stroke-width="3"/></svg></div></div><div id="transformOpts">${t.opts.map((o,i)=>`<button class="quiz-option" data-trans="${i}">${o}</button>`).join('')}</div><div id="transformFeedback"></div></article>`;$$('[data-trans]').forEach(b=>b.onclick=()=>{if(b.disabled)return;$$('[data-trans]').forEach(x=>x.disabled=true);const ok=+b.dataset.trans===t.a;if(ok)correct++;$('#transformFeedback').innerHTML=`<div class="quiz-feedback">${ok?'Tepat!':'Belum tepat.'} ${t.why}<div class="inline-actions"><button class="btn btn-small" id="transNext">${idx===tasks.length-1?'Lihat hasil':'Berikutnya'} →</button></div></div>`;$('#transNext').onclick=()=>{idx++;if(idx<tasks.length)show();else{state.score+=correct*5;state.best=Math.max(state.best,correct);save();awardBadges();$('#gameArea').innerHTML=`<article class="detail-article"><h2>Latihan selesai</h2><p>Jawaban benar ${correct}/${tasks.length}. Kamu mendapat ${correct*5} poin.</p><button class="btn" id="transAgain">Ulangi</button></article>`;$('#transAgain').onclick=startTransform;renderHome();renderProgress()}}})}show()}
function startTiling(){const shapes=[{name:'Segitiga sama sisi',angle:60},{name:'Persegi',angle:90},{name:'Segilima beraturan',angle:108},{name:'Segienam beraturan',angle:120},{name:'Segidelapan beraturan',angle:135}];$('#gameArea').innerHTML=`<article class="detail-article"><p class="eyebrow">Gim pengubinan</p><h2>Apakah bentuk ini bisa mengubin sendiri?</h2><p>Pilih bentuk. Hitung berapa sudut dalam yang diperlukan agar jumlahnya tepat 360° di satu titik.</p><label for="tileShape">Pilih bentuk</label><select id="tileShape" class="field">${shapes.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('')}</select><div id="tileResult" class="quiz-feedback" style="margin-top:18px"></div><div class="inline-actions"><button class="btn" id="checkTile">Periksa jawaban</button><button class="btn btn-ghost" id="showTileHint">Petunjuk</button></div><div id="tileHint"></div></article>`;const update=()=>{const s=shapes[+$('#tileShape').value],count=360/s.angle,integer=Number.isInteger(count);$('#tileResult').innerHTML=`<b>Sudut dalam: ${s.angle}°</b><br>360° ÷ ${s.angle}° = ${count.toFixed(2).replace(/\.00$/,'')}<br>${integer?`Pas: ${count} bentuk bertemu tepat di satu titik.`:'Bukan bilangan bulat: bentuk ini tidak dapat mengubin bidang sendiri dengan susunan sudut yang sama di satu titik.'}`};$('#checkTile').onclick=()=>{update();state.score+=5;save();toast('+5 poin untuk mencoba');};$('#tileShape').onchange=update;$('#showTileHint').onclick=()=>$('#tileHint').innerHTML='<p class="callout">Jumlah sudut di satu titik harus tepat 360°. Kurang dari 360° meninggalkan celah; lebih dari 360° menyebabkan tumpang tindih.</p>';update();}
function startOrder(){const steps=['Siapkan kanvas dan sumbu koordinat.','Gambar bentuk dasar menggunakan Polygon.','Cerminkan bentuk terhadap garis yang dipilih.','Buat slider sudut dan putar bentuk terhadap pusat.'];let list=steps.map((s,i)=>({s,correct:i})).sort(()=>Math.random()-.5);$('#gameArea').innerHTML=`<article class="detail-article"><p class="eyebrow">Susun langkah</p><h2>Urutkan rekonstruksi motif di GeoGebra</h2><p class="muted">Gunakan tombol naik/turun untuk menyusun langkah dari awal hingga akhir.</p><div id="orderList">${list.map((x,i)=>`<div class="order-row" data-order="${i}" style="display:flex;align-items:center;gap:8px;margin:8px 0;padding:12px;border:1px solid var(--line);border-radius:13px;background:var(--paper)"><span style="flex:1">${safe(x.s)}</span><button class="btn btn-small btn-ghost" data-up="${i}" ${i===0?'disabled':''}>↑</button><button class="btn btn-small btn-ghost" data-down="${i}" ${i===list.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="btn" id="checkOrder">Periksa urutan</button><div id="orderResult"></div></article>`;function redraw(){const box=$('#orderList');box.innerHTML=list.map((x,i)=>`<div class="order-row" data-order="${i}" style="display:flex;align-items:center;gap:8px;margin:8px 0;padding:12px;border:1px solid var(--line);border-radius:13px;background:var(--paper)"><span style="flex:1">${safe(x.s)}</span><button class="btn btn-small btn-ghost" data-up="${i}" ${i===0?'disabled':''}>↑</button><button class="btn btn-small btn-ghost" data-down="${i}" ${i===list.length-1?'disabled':''}>↓</button></div>`).join('');$$('[data-up]').forEach(b=>b.onclick=()=>{let i=+b.dataset.up;[list[i-1],list[i]]=[list[i],list[i-1]];redraw()});$$('[data-down]').forEach(b=>b.onclick=()=>{let i=+b.dataset.down;[list[i+1],list[i]]=[list[i],list[i+1]];redraw()})}redraw();$('#checkOrder').onclick=()=>{const ok=list.every((x,i)=>x.correct===i);$('#orderResult').innerHTML=`<div class="quiz-feedback">${ok?'Benar! Urutannya logis. +20 poin.':'Belum tepat. Coba mulai dari menyiapkan kanvas, lalu menggambar bentuk dasar.'}</div>`;if(ok){state.score+=20;save();awardBadges();renderHome();renderProgress()}};}
function renderProgress(){const p=$('#page-progres');p.innerHTML=`<p class="eyebrow">Perjalanan saya</p><h1 class="page-title">Setiap langkah adalah pencapaian.</h1><p class="lead">Semua data ini tersimpan di browser/perangkat yang sedang kamu gunakan. Data tidak dikirim ke server.</p><div class="dashboard-grid"><article class="panel progress-panel"><div class="panel-top"><h3>Ringkasan perjalanan</h3><span class="pill">${Math.round(state.completed.length/6*100)}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${state.completed.length/6*100}%"></div></div><div class="progress-caption"><span>Bab selesai: ${state.completed.length}/6</span><span>Total poin: ${state.score}</span></div></article><article class="panel daily-panel"><h3>📈 Rekor kuis</h3><p class="muted">Jawaban benar terbaik dalam satu sesi</p><div style="font:600 3rem 'Playfair Display',serif;color:var(--red2)">${state.best}</div><button class="btn btn-small" data-page="games">Main lagi</button></article></div><div class="section-head"><div><h2>Lencana pencapaian</h2><p>Lencana terbuka saat kamu menyelesaikan aktivitas.</p></div></div><div class="achievement-grid">${badgeList.map(([icon,title,desc,key])=>`<article class="achievement-card ${hasBadge(key)?'earned':''}"><span class="badge-icon">${icon}</span><h4>${title}</h4><p>${desc}</p><span class="pill" style="margin-top:10px">${hasBadge(key)?'Terbuka':'Belum terbuka'}</span></article>`).join('')}</div><div class="section-head"><div><h2>Karya tersimpan</h2><p>Unduh PNG ketika membuat karya di Studio. Ringkasan karya disimpan di sini.</p></div></div>${state.works.length?`<div class="chapter-grid">${state.works.slice().reverse().map(w=>`<article class="chapter-card"><span class="pill">Karya kreatif</span><h3>${safe(w.name)}</h3><p>Dibuat: ${safe(w.date)}<br>Rotasi ${w.rotation}° · Skala ${w.scale}× · Cermin ${w.mirror?'aktif':'nonaktif'}</p><span class="muted">Warna utama: ${safe(w.color)}</span></article>`).join('')}</div>`:'<div class="empty-state">Belum ada karya. Kunjungi Studio Kreasi untuk membuat motif pertamamu.</div>'}<div class="inline-actions"><button class="btn btn-ghost" id="exportProgress">Ekspor progres (JSON) ↓</button><button class="btn btn-ghost" id="resetProgress">Atur ulang progres</button></div>`;$('#exportProgress').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='progres-anyaman-semesta.json';a.click();URL.revokeObjectURL(a.href)};$('#resetProgress').onclick=()=>{if(confirm('Hapus progres lokal, skor, dan karya dari perangkat ini?')){state.completed=[];state.score=0;state.best=0;state.works=[];state.badges=[];state.dailyDone=false;save();renderProgress();renderHome();toast('Progres lokal diatur ulang')}};}
function hasBadge(key){return state.badges.includes(key)}function awardBadges(){const tests={firstChapter:state.completed.length>=1,quiz:state.best>=1||state.score>=5,work:state.works.length>=1,threeChapters:state.completed.length>=3,allChapters:state.completed.length>=6,highScore:state.best>=8};Object.entries(tests).forEach(([k,v])=>{if(v&&!state.badges.includes(k)){state.badges.push(k);const b=badgeList.find(x=>x[3]===k);if(b)toast('Lencana baru: '+b[1])}});save()}
function renderGlossary(){const p=$('#page-glosarium');p.innerHTML=`<p class="eyebrow">Kamus mini</p><h1 class="page-title">Istilah, dengan bahasa sederhana.</h1><p class="lead">Cari istilah yang kamu temukan dalam materi. Definisi matematika menjelaskan konsep; istilah budaya dan agama mengikuti konteks yang dibahas dalam buku dan sumber terkait.</p><input id="glossarySearch" class="field" placeholder="Cari istilah…" style="width:100%;max-width:520px;margin:18px 0"><div id="glossaryGrid" class="glossary-grid">${glossary.map(([t,d])=>`<article class="glossary-item" data-term="${safe((t+' '+d).toLowerCase())}"><b>${safe(t)}</b><p>${safe(d)}</p></article>`).join('')}</div>`;$('#glossarySearch').oninput=()=>{const q=$('#glossarySearch').value.toLowerCase();$$('[data-term]').forEach(x=>x.style.display=x.dataset.term.includes(q)?'':'none')};}
function renderReferences(){const p=$('#page-referensi');p.innerHTML=`<p class="eyebrow">Referensi dan atribusi</p><h1 class="page-title">Belajar dengan sumber yang jelas.</h1><p class="lead">Daftar ini memuat sumber yang tercantum atau disebut dalam bahan Anyaman Semesta serta sumber tambahan untuk galeri. Daftar pustaka lengkap buku tetap perlu disalin dari halaman daftar pustaka naskah asli; jangan menganggap daftar ringkas ini menggantikannya.</p><article class="detail-article"><h2>Sumber utama</h2><ul class="reference-list"><li><b>Buku Anyaman Semesta: Menyibak Simetri dan Tauhid dalam Batik Sulawesi Selatan.</b> Bahan materi utama yang dikirim pengguna. Bagian daftar pustaka lengkap perlu diperiksa dari buku sumber.</li><li><b>iWareBatik — Sulawesi Selatan.</b> Informasi wilayah, inspirasi motif Toraja dan Bugis, Pa’tedong, Lontara, serta La Galigo. <a href="https://www.iwarebatik.org/south-sulawesi/?lang=id" target="_blank" rel="noopener">Buka sumber ↗</a></li><li><b>iWareBatik — Paqbarre Allo.</b> Keterangan motif dan makna yang diterbitkan. <a href="https://www.iwarebatik.org/paqbarre-allo/?lang=id" target="_blank" rel="noopener">Buka sumber ↗</a></li><li><b>iWareBatik — Lontara.</b> Keterangan tentang aksara tradisional Bugis-Makassar. <a href="https://www.iwarebatik.org/lontara/?lang=id" target="_blank" rel="noopener">Buka sumber ↗</a></li><li><b>iWareBatik — La Galigo.</b> Keterangan tentang karya sastra epik Bugis dan inspirasi motif. <a href="https://www.iwarebatik.org/la-galigo/?lang=id" target="_blank" rel="noopener">Buka sumber ↗</a></li><li><b>iWareBatik — Tongkonan.</b> <a href="https://www.iwarebatik.org/tongkonan/?lang=id" target="_blank" rel="noopener">Buka sumber ↗</a></li><li><b>Nurdin, A. E. (2024).</b> “Analisis Perkembangan Motif Batik Sulawesi Selatan.” <i>Keraton: Journal of History Education and Culture</i>, 6(1). <a href="https://doi.org/10.32585/keraton.v6i1.5421" target="_blank" rel="noopener">https://doi.org/10.32585/keraton.v6i1.5421</a></li><li><b>GeoGebra Classic.</b> Perangkat untuk konstruksi geometri dan eksplorasi transformasi. <a href="https://www.geogebra.org/classic" target="_blank" rel="noopener">Buka GeoGebra ↗</a></li></ul><div class="callout"><b>Catatan penting:</b> iWareBatik menyatakan konten dan gambar dilindungi dan meminta penggunaan gambar disertai rujukan situs asli. Karena itu, setiap kartu galeri menyediakan tautan sumber. Jika APK akan didistribusikan luas atau dipublikasikan, periksa izin dan ketentuan pemakaian gambar sebelum membundel salinannya secara offline.</div></article>`;}
function renderAbout(){ $('#page-tentang').innerHTML=`<p class="eyebrow">Tentang proyek</p><h1 class="page-title">Anyaman Semesta</h1><p class="lead">Menyibak Simetri dan Tauhid dalam Batik Sulawesi Selatan.</p><article class="detail-article"><h2>Matematika × Budaya × Islam</h2><p>Anyaman Semesta adalah pengalaman belajar interaktif yang mengajak pengguna melihat motif sebagai pintu masuk untuk mengamati pola, bentuk, simetri, transformasi geometri, dan nilai budaya. Aplikasi menggabungkan materi, galeri, eksperimen visual, permainan, dan refleksi.</p><h3>Prinsip pembelajaran</h3><ul><li>Mulai dari apa yang terlihat, baru kemudian menafsirkan.</li><li>Uji konsep matematika dengan pengukuran atau konstruksi yang dapat diulang.</li><li>Cantumkan sumber ketika menjelaskan budaya dan filosofi motif.</li><li>Jadikan refleksi spiritual sebagai ruang pemaknaan, bukan sebagai pengganti bukti matematika.</li></ul><h3>Privasi</h3><p>Progres, skor, dan ringkasan karya disimpan di penyimpanan lokal browser/perangkat. Tidak ada akun atau server yang digunakan oleh versi ini. Foto galeri dimuat dari situs sumber ketika perangkat terhubung ke internet.</p><div class="callout">Dikembangkan sebagai media pembelajaran. Untuk penulisan daftar pustaka dan keterangan tim, masukkan informasi resmi dari buku asli sebelum publikasi.</div></article>`;}
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');$$('[data-close-modal]').forEach(b=>b.onclick=closeModal);$$('[data-page]',$('#modalBody')).forEach(b=>b.onclick=()=>{closeModal();go(b.dataset.page)});$('#modal').querySelector('.modal-card').scrollTop=0}function closeModal(){$('#modal').classList.add('hidden')}

// Logo di samping menu menjadi sakelar musik: satu tekan mulai, tekan berikutnya berhenti.
function setupLogoMusic(){const btn=$('#musicLogoBtn'),audio=$('#appMusic');if(!btn||!audio)return;btn.addEventListener('click',async()=>{if(audio.paused){try{await audio.play();btn.classList.add('is-playing');btn.setAttribute('aria-pressed','true');btn.setAttribute('aria-label','Hentikan musik Anyaman Semesta');toast('Musik diputar · tekan logo lagi untuk berhenti')}catch(e){toast('Musik belum dapat diputar. Coba tekan logo sekali lagi atau periksa file audio.')}}else{audio.pause();audio.currentTime=0;btn.classList.remove('is-playing');btn.setAttribute('aria-pressed','false');btn.setAttribute('aria-label','Putar musik Anyaman Semesta');toast('Musik dihentikan')}});audio.addEventListener('ended',()=>{btn.classList.remove('is-playing');btn.setAttribute('aria-pressed','false')});}

const pageRenderers={home:renderHome,materi:renderChapters,galeri:renderGallery,studio:renderStudio,games:renderGames,progres:renderProgress,glosarium:renderGlossary,referensi:renderReferences,tentang:renderAbout};function go(page){if(!pageRenderers[page])return;$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));state.lastPage=page;save();if(!$('#page-'+page).dataset.rendered||['home','progres'].includes(page)){pageRenderers[page]();$('#page-'+page).dataset.rendered='1'}else if(page==='galeri')renderGallery();else if(page==='studio')renderStudio();else if(page==='games')renderGames();$('#main').scrollTo({top:0,behavior:'smooth'});closeDrawer();}
function openDrawer(){$('#drawer').classList.add('open');$('#scrim').classList.add('open');$('#menuBtn').setAttribute('aria-expanded','true')}function closeDrawer(){$('#drawer').classList.remove('open');$('#scrim').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false')}
$('#startBtn').onclick=()=>{$('#splash').classList.add('exit');setTimeout(()=>{$('#splash').classList.add('hidden');$('#app').classList.remove('hidden');go('home')},260)};$('#menuBtn').onclick=()=>$('#drawer').classList.contains('open')?closeDrawer():openDrawer();$('#scrim').onclick=closeDrawer;$('#homeBtn').onclick=()=>go('home');$$('[data-page]').forEach(b=>{if(b.closest('#modalBody'))return;b.addEventListener('click',()=>go(b.dataset.page))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeModal()}if(e.key==='Enter'&&e.target.matches('[data-card-motif]'))openMotif(+e.target.dataset.cardMotif)});document.addEventListener('click',e=>{const studioButton=e.target.closest('[data-studio-motif]');if(studioButton){e.preventDefault();e.stopPropagation();studioMotifIndex=+studioButton.dataset.studioMotif;studioPhoto=motifs[studioMotifIndex].photoUrl||null;go('studio');return}const pageButton=e.target.closest('[data-page]');if(pageButton&&!e.target.closest('#modalBody')){e.preventDefault();go(pageButton.dataset.page)}const card=e.target.closest('[data-card-motif]');if(card&&!e.target.closest('a'))openMotif(+card.dataset.cardMotif);const chapter=e.target.closest('[data-chapter]');if(chapter){go('materi');setTimeout(()=>showChapter(+chapter.dataset.chapter),80)}});
function applyTheme(){document.body.classList.toggle('dark',state.theme==='dark');document.querySelector('meta[name="theme-color"]').content='#101a2a'}/* Tema gelap dibuat permanen sesuai permintaan; tombol tema tidak lagi mengubah palet. */
applyTheme();renderHome();$('#page-home').dataset.rendered='1';$('#app').classList.add('hidden');

if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',setupLogoMusic)}else{setupLogoMusic()}
